scenario.en:
// middleware.ts — shipped without a matcher
import { NextResponse } from 'next/server';

export function middleware(req: Request) {
  const res = NextResponse.next();
  if (!req.headers.get('cookie')?.includes('bucket=')) {
    res.cookies.set('bucket', Math.random() < 0.5 ? 'a' : 'b');
  }
  return res;
}

// no `export const config = { matcher: ... }` anywhere

